window.ScripturaLexicons.BDAG_PART_0278 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-01\" data-source=\"BDAG\" data-search=\"πεζός, ή, όν adjetivo que vai por terra; pedestre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πεζός, ή, όν</td><td>adjetivo</td><td>que vai por terra; pedestre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-02\" data-source=\"BDAG\" data-search=\"πειθαρχέω verbo obedecer; submeter-se à autoridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πειθαρχέω</td><td>verbo</td><td>obedecer; submeter-se à autoridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-03\" data-source=\"BDAG\" data-search=\"πειθός, ή, όν adjetivo persuasivo; convincente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πειθός, ή, όν</td><td>adjetivo</td><td>persuasivo; convincente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-04\" data-source=\"BDAG\" data-search=\"πειθώ, οῦς, ἡ substantivo feminino persuasão; capacidade de persuadir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πειθώ, οῦς, ἡ</td><td>substantivo feminino</td><td>persuasão; capacidade de persuadir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-05\" data-source=\"BDAG\" data-search=\"πείθω verbo convencer; persuadir; confiar; obedecer; estar certo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πείθω</td><td>verbo</td><td>convencer; persuadir; confiar; obedecer; estar certo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-06\" data-source=\"BDAG\" data-search=\"Πειλᾶτος remissão de nome próprio ver Πιλᾶτος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πειλᾶτος</td><td>remissão de nome próprio</td><td>ver Πιλᾶτος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-07\" data-source=\"BDAG\" data-search=\"πεῖν remissão verbal ver πίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πεῖν</td><td>remissão verbal</td><td>ver πίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-08\" data-source=\"BDAG\" data-search=\"πεινάω verbo ter fome; desejar ardentemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πεινάω</td><td>verbo</td><td>ter fome; desejar ardentemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-09\" data-source=\"BDAG\" data-search=\"πεῖρα, ας, ἡ substantivo feminino tentativa; prova; experiência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πεῖρα, ας, ἡ</td><td>substantivo feminino</td><td>tentativa; prova; experiência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-10\" data-source=\"BDAG\" data-search=\"πειράζω verbo tentar; pôr à prova; testar; seduzir ao pecado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πειράζω</td><td>verbo</td><td>tentar; pôr à prova; testar; seduzir ao pecado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-11\" data-source=\"BDAG\" data-search=\"πειρασμός, οῦ, ὁ substantivo masculino prova; provação; tentação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πειρασμός, οῦ, ὁ</td><td>substantivo masculino</td><td>prova; provação; tentação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-12\" data-source=\"BDAG\" data-search=\"πειράω verbo médio tentar; empreender; experimentar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πειράω</td><td>verbo médio</td><td>tentar; empreender; experimentar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-13\" data-source=\"BDAG\" data-search=\"πεισμονή, ῆς ἡ substantivo feminino persuasão; influência persuasiva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πεισμονή, ῆς ἡ</td><td>substantivo feminino</td><td>persuasão; influência persuasiva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-14\" data-source=\"BDAG\" data-search=\"πέλαγος, ους, τό substantivo neutro alto-mar; mar aberto; mar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέλαγος, ους, τό</td><td>substantivo neutro</td><td>alto-mar; mar aberto; mar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-15\" data-source=\"BDAG\" data-search=\"πέλας advérbio substantivado perto; próximo; vizinho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέλας</td><td>advérbio substantivado</td><td>perto; próximo; vizinho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-16\" data-source=\"BDAG\" data-search=\"πελεκίζω verbo decapitar com machado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πελεκίζω</td><td>verbo</td><td>decapitar com machado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-17\" data-source=\"BDAG\" data-search=\"πεμπταῖος, α, ον adjetivo do quinto dia; no quinto dia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πεμπταῖος, α, ον</td><td>adjetivo</td><td>do quinto dia; no quinto dia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-18\" data-source=\"BDAG\" data-search=\"πέμπτος, η, ον adjetivo numeral ordinal quinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέμπτος, η, ον</td><td>adjetivo numeral ordinal</td><td>quinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-19\" data-source=\"BDAG\" data-search=\"πέμπω verbo enviar pessoas, mensageiros, objetos ou mensagens BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέμπω</td><td>verbo</td><td>enviar pessoas, mensageiros, objetos ou mensagens</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0278-20\" data-source=\"BDAG\" data-search=\"πένης, ητος substantivo e adjetivo pobre; pessoa que trabalha para sobreviver BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πένης, ητος</td><td>substantivo e adjetivo</td><td>pobre; pessoa que trabalha para sobreviver</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0278-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεζός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πεζός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">πεζεύω</span>; Hom. e outros; inscrições, papiros, LXX), que segue por terra (Hom. e outros; Jos., Bell. 3, 8) (em oposição a <span class=\"greek\">ἐν</span> <span class=\"greek\">πλοίῳ</span>, como Pind., P. 10, 29 <span class=\"greek\">ναυσί</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:13</a>, variante textual. <span class=\"greek\">πεζοὺς</span> <span class=\"greek\">πέμπειν</span> «enviar mensageiros (que viajam pela estrada)» IPol 8:1.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πειθαρχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πειθαρχέω</span>, futuro, 3.ª pessoa do plural <span class=\"greek\">πειθαρχήσουσιν</span> Da 7:27; particípio do 1.º aoristo <span class=\"greek\">πειθαρχήσας</span> (Soph., Hdt.+; M. Ant. 5, 9; inscrições, papiros, LXX, Did. Frequente em Philo; Jos., Bell. 1, 454, C. Ap. 2, 293 <span class=\"greek\">τ</span>. <span class=\"greek\">νόμοις</span>), obedecer, <span class=\"greek\">θεῷ</span> «a Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:29</a> (cf. Pla., Apol. 17, 29d <span class=\"greek\">πείσομαι</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ὑμῖν</span>; Socrat., Ep. 1, 7 <span class=\"greek\">ᾧ</span> [= <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span>] <span class=\"greek\">πειστέον</span> <span class=\"greek\">μᾶλλον</span>; Jos., Ant. 17, 159; Theoph. Ant. 1, 14 [p. 90, 2]), v. 32. <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> «obedecer à palavra da justiça» Pol 9:1. <span class=\"greek\">ἔδει</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">πειθαρχήσαντάς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀνάγεσθαι</span> «deveríeis ter seguido meu conselho e não ter navegado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:21</a> (cf. Polyb. 3, 4, 3.—Sobre o assunto, cf. o protesto inútil de um passageiro em Ael. Aristid. 48, 47f K.=24 p. 483 D.). Figuradamente, acerca dos corpos celestes que obedecem ao Criador, Dg 7:2. Absolutamente (como OGI 483, 70f), ser obediente Tit 3:1 (com <span class=\"greek\">ἀρχαῖς</span> <span class=\"greek\">ἐξουσίαις</span> <span class=\"greek\">ὑποτάσσεσθαι</span>).—ENachmanson, D. Konstruktionen v. <span class=\"greek\">πειθαρχεῖν</span> in d. <span class=\"greek\">κοινή</span>: Eranos 10, 1910, 201–3.—New Docs 2, 105. DELG s.v. <span class=\"greek\">ἄρχω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πειθός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πειθός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (de <span class=\"greek\">πείθ</span>[<span class=\"greek\">ω</span>]), persuasivo: <span class=\"greek\">ἐν</span> <span class=\"greek\">πειθοῖς</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">λόγοις</span> «em palavras persuasivas de sabedoria» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:4</a>. A palavra não é encontrada em nenhum outro lugar; sua atestação é excepcionalmente boa (já em P46), embora se encontre em contexto sujeito a variações consideráveis de pormenor (situação bem examinada por Ltzm., Hdb. ad loc.). A palavra foi formada em plena conformidade com o uso grego padrão (cf. <span class=\"greek\">φειδός</span> «parcimonioso» de <span class=\"greek\">φείδομαι</span>), e os Padres gregos a aceitaram sem comentário (assim Ltzm., Bachmann, Sickenberger, Herm-vSoden; Mlt-H. 78). Apesar disso, muitos (por exemplo Heinrici, Schmiedel, JWeiss) rejeitam essa palavra por causa de sua raridade e preferem a explicação de que teve origem numa ditografia do <span class=\"greek\">ς</span> (ou talvez em erro de audição de uma passagem ditada): <span class=\"greek\">ἐν</span> <span class=\"greek\">πειθοῖ</span> <span class=\"greek\">σοφίας</span>, veja <span class=\"greek\">πειθώ</span>; B-D-F §47, 4; 112; W-S. §16, 3 n. 20; Rob. 157; GZuntz, The Text of the Epistles ’53, 23–25.—Rdm.2 p. 63 toma <span class=\"greek\">πειθοῖς</span> como formação rara do genitivo de <span class=\"greek\">πειθώ</span>, influenciada pelo dativo <span class=\"greek\">πειθοῖ</span>; nesse caso, o significado seria «palavras de persuasão da (própria) sabedoria».—DELG s.v. <span class=\"greek\">πείθομαι</span> B. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πειθώ, οῦς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πειθώ</span>, <span class=\"greek\">οῦς</span>, <span class=\"greek\">ἡ</span>, dom ou arte da persuasão, poder persuasivo (cf. <span class=\"greek\">πειθός</span>; Aeschyl., Thu. e outros; Ps.-Phoc. 78; Philo; Jos., Bell. 2, 8, C. Ap. 2, 186; 223; Just., A I, 53, 12, D. 53, 6; Jos.); <span class=\"greek\">ἐν</span> <span class=\"greek\">πειθοῖ</span> <span class=\"greek\">ἀνθρωπίνης</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">λόγοις</span> (outros leem <span class=\"greek\">λογῶν</span>,-<span class=\"greek\">γοῦ</span>, que por vezes está ausente; veja JWeiss ad loc.) «com o poder persuasivo da sabedoria» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:4</a>, variante textual (veja <span class=\"greek\">πειθός</span>. Sobre o «poder persuasivo» das palavras, cf. <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 17, 1 <span class=\"greek\">πειθὼ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span>; Philo, Virt. 217 <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">πειθώ</span>; Jos., Ant. 2, 272).—DELG s.v. <span class=\"greek\">πείθομαι</span> B. M-M. s.v. <span class=\"greek\">πειθός</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πείθω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πείθω</span> (Hom. e outros; inscrições, papiros, LXX, EpArist, Philo, Joseph., Test12Patr), imperfeito <span class=\"greek\">ἔπειθον</span>; futuro <span class=\"greek\">πείσω</span>; 1.º aoristo <span class=\"greek\">ἔπεισα</span>, imperativo <span class=\"greek\">πεῖσον</span>; 1.º perfeito, 3.ª pessoa do singular <span class=\"greek\">πέπεικε</span>(<span class=\"greek\">ν</span>) (Just., D. 53, 5; 58, 2); 2.º perfeito <span class=\"greek\">πέποιθα</span>; mais-que-perfeito <span class=\"greek\">ἐπεποίθειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:22</a> e <span class=\"greek\">ἐπεποίθησα</span> Job 31:24 (cf. Judg 9:26 A; Zech 3:3). Médio e passivo: imperfeito <span class=\"greek\">ἐπειθόμην</span>. Passivo: 1.º futuro <span class=\"greek\">πεισθήσομαι</span>; 1.º aoristo <span class=\"greek\">ἐπείσθην</span>; perfeito <span class=\"greek\">πέπεισμαι</span>; mais-que-perfeito, 1.ª pessoa do plural (<span class=\"greek\">ἐ</span>)<span class=\"greek\">πεπείσμεθα</span> (Ath. 31, 2).<br><br>① Voz ativa, exceto o 2.º perfeito e o mais-que-perfeito: levar alguém a adotar determinada opinião ou maneira de agir.<br><br>ⓐ Convencer, com acusativo de pessoa (X., Mem. 1, 2, 45 e outros) ISm 5:1. <span class=\"greek\">ἔπειθεν</span> <span class=\"greek\">Ἰουδαίους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἕλληνας</span> «tentava convencer judeus e gregos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:4</a>. <span class=\"greek\">πείθων</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> «procurando convencê-los a respeito de Jesus» 28:23 (<span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> como Jos., C. Ap. 2, 153). Sem acusativo, <span class=\"greek\">πείθων</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> 19:8, variante textual. Com acusativo de coisa, <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> 28:23, variante textual, e <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> 19:8 (sobre o acusativo de coisa, cf. Hdt. 1, 163; Pla., Apol. 27, 37a). Absolutamente (Jos., Vi. 19): <span class=\"greek\">πείθων</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">βιαζόμενος</span> «convencendo, não constrangendo» Dg 7:4.—Também de convencer alguém da correção de ensinos reprováveis, quase equivalente a induzir ao erro (Ps.-Clem., Hom. 1, 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:26</a>. <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> «alguém mediante alguma coisa» Hs 8, 6, 5.<br><br>ⓑ Persuadir, apelar a, também em sentido desfavorável, bajular, induzir ao erro (assim TestDan 1:8; ApcMos 21; Jos., C. Ap. 2, 201), <span class=\"greek\">τινά</span> «alguém», <span class=\"greek\">ἀνθρώπους</span> (Ael. Aristid. 34, 19 K.=50 p. 552 D.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:11</a>; talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:10</a> (mas veja c abaixo). Cf. MPol 3:1; 8:2, 3. <span class=\"greek\">τινά</span> seguido de infinitivo (X., An. 1, 3, 19; Polyb. 4, 64, 2; Diod S 12, 39, 2; 17, 15, 5; Herodian 2, 4, 2; Jos., Ant. 8, 256; Just., A II 2, 10, D. 112, 3; Tat. 21, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a>; MPol 4; 5:1. <span class=\"greek\">ἔπειθεν</span> (subentende-se <span class=\"greek\">αὐτὸν</span>) <span class=\"greek\">ἀρνεῖσθαι</span> «tentava induzi-lo a negar» 9:2. Talvez pertença aqui a passagem textualmente incerta de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:28</a>, na voz passiva: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀλίγῳ</span> <span class=\"greek\">με</span> <span class=\"greek\">πείθεις</span> <span class=\"greek\">Χριστιανὸν</span> <span class=\"greek\">ποιῆσαι</span> «não perdes tempo tentando fazer-me representar o papel de cristão» (cf. tradução em Beginn. IV 322, com referências a 3 Km 20:7 e a autores patrísticos citados em Soph., Lex. s.v. <span class=\"greek\">ποιέω</span> 3; veja também Lampe s.v. <span class=\"greek\">ποιέω</span> C). Devido a aparente incompreensão do idioma, essa redação é simplificada numa variante textual muito difundida, em que <span class=\"greek\">ποιῆσαι</span> é substituído por <span class=\"greek\">γενέσθαι</span>: «em pouco tempo estás me persuadindo (ou tentando persuadir) a tornar-me cristão» (cf. Jos., Vi. 151 <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">ἐπείθοντο</span> = «estavam quase persuadidos»), provavelmente com sentido irônico. Bauer considerou provável que a leitura do texto devesse ser entendida como combinação de duas expressões, «em pouco tempo estás me persuadindo a tornar-me cristão» e «em pouco tempo me farás cristão», de modo que o sentido fosse semelhante a «tens pressa em me persuadir e fazer de mim um cristão» (assim Goodsp, Probs. 137f [mas não está claro se «fazer» deve ser entendido no sentido de «representar o papel de»]. Veja a bibliografia s.v. <span class=\"greek\">ὀλίγος</span> 2b<span class=\"greek\">β</span> e em 3a abaixo, também AFridrichsen, SymbOsl 14, ’35, 49–52, ConNeot 3, ’39, 13–16 [com referência a X., Mem. 1, 2, 49; cf. PBenoit, RB 53, ’46, 303]; DHesseling, Neophilol 20, ’37, 129–34; JHarry, ATR 28, ’46, 135 f; EHaenchen ad loc.). Em lugar do infinitivo, emprega-se <span class=\"greek\">ἵνα</span> (Plut., Mor. 181a <span class=\"greek\">πείθωμεν</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">μείνῃ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:20</a> (B-D-F §392, 1e; Rob. 993).<br><br>ⓒ Conquistar a adesão de alguém, procurar agradar (X., Cyr. 6, 1, 34; 2 Macc 4:45) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:20</a>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">ὄχλους</span> 14:19. Assim, talvez, também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:10</a> (veja b acima.—<span class=\"greek\">π</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> = «persuadir Deus»: Jos., Ant. 4, 123; 8, 256; Ps.-Clem., Hom. 3, 64).—BDodd, NTS 42, ’96, 90–104.<br><br>ⓓ Conciliar, apaziguar, tranquilizar (Hom. e outros), <span class=\"greek\">τὸν</span> <span class=\"greek\">δῆμον</span> (cf. X., Hell. 1, 7, 7 <span class=\"greek\">τοιαῦτα</span> <span class=\"greek\">λέγοντες</span> <span class=\"greek\">ἔπειθον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">δῆμον</span>) MPol 10:2. <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> (variante textual <span class=\"greek\">τὰ</span> <span class=\"greek\">καρδία</span>) <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:19</a> (mas o texto está em estado insatisfatório). Conciliar, satisfazer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:14</a> (a menos que se pretenda «subornar», <span class=\"greek\">π</span>. <span class=\"greek\">ἀργυρίῳ</span>: escólio sobre Pla. 18b; 2 Macc 10:20; Jos., Ant. 14, 281; 490).<br><br>② O 2.º perfeito (com mais-que-perfeito) possui sentido presente (B-D-F §341; Rob. 881): estar tão convencido que se deposita confiança em algo.<br><br>ⓐ Depender de, confiar em, com dativo de pessoa ou coisa (Hom. e outros; 4 Km 18:20; Pr 14:16; 28:26; Sir 32:24; Wsd 14:29; Is 28:17), <span class=\"greek\">τίνι</span> <span class=\"greek\">θεῷ</span> «em qual Deus» Dg 1 (aqui <span class=\"greek\">πέπ</span>. com dativo é quase equivalente a «crer em», acepção da qual <span class=\"greek\">πέπ</span>. também se aproxima na LXX; cf. Jos., Ant. 7, 122). <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεσμοῖς</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑπακοῆ</span> <span class=\"greek\">σου</span> Phlm 21. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> «em alguém ou alguma coisa» (PSI 646, 3 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σοὶ</span> <span class=\"greek\">πεποιθώς</span>; LXX; SibOr 3, 545; Syntipas p. 52, 5; Just., D. 8, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:43</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:24</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:13</a> (Is 8:17); B 9:4; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλπίδι</span> 1 Cl 57:7; seguido de <span class=\"greek\">ὅτι</span> (Syntipas p. 32, 6; 35, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:9</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (Ps 117:8; Acta Christophori [ed. HUsener 1886] 68, 10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:43</a>; 1 Cl 60:1, cf. 58:1; Hm 9:6; Hs 9, 18, 5; seguido de <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:4</a>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Jdth 2:5) «em alguém ou alguma coisa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:3f</a>; seguido de <span class=\"greek\">ὅτι</span>, 2:24. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> (Wsd 16:24, variante textual), seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:10</a>.<br><br>ⓑ Estar convencido, seguro, certo, seguido de acusativo e infinitivo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:19</a>. Seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a>, variante textual. <span class=\"greek\">πεποιθὼς</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὅτι</span> «certo precisamente disto, a saber, que» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:6</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">πεποιθὼς</span> <span class=\"greek\">οἶδα</span> <span class=\"greek\">ὅτι</span> «convencido disso, sei que» 1:25. <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">πέποιθεν</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">εἶναι</span> «se alguém está convencido, em seu íntimo, de que pertence a Cristo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:7</a> (cf. BGU 1141, 17 [14 a.C.] <span class=\"greek\">πέποιθα</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐμαυτῷ</span>).<br><br>③ Passivo e médio, exceto o perfeito: ser conquistado como resultado de persuasão.<br><br>ⓐ Deixar-se persuadir, crer, absolutamente (Pr 26:25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a>, variante textual. <span class=\"greek\">μὴ</span> <span class=\"greek\">πειθομένου</span> <span class=\"greek\">αὐτοῦ</span> «visto que ele não se deixava persuadir» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:14</a>. <span class=\"greek\">πεισθεὶς</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Νάβαλ</span> AcPl Ha 6, 23. Com dativo daquilo pelo qual alguém é persuadido (oposto a <span class=\"greek\">ἀπιστεῖν</span>; <span class=\"greek\">τοῖς</span> <span class=\"greek\">γραώδεσι</span> <span class=\"greek\">μύθοις</span> Iren. 1, 16, 3 [Harv. I 162, 8]): <span class=\"greek\">τοῖς</span> <span class=\"greek\">λεγομένοις</span> (Hdt. 2, 146, 1; Jos., Bell. 7, 415) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:24</a>. <span class=\"greek\">πείθομαι</span> «creio», seguido de <span class=\"greek\">ὅτι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a>; Hs 8, 11, 2. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:28</a>, variante textual (veja 1b acima), construído com infinitivo: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀλίγῳ</span> <span class=\"greek\">με</span> <span class=\"greek\">πείθῃ</span> <span class=\"greek\">Χριστιανὸν</span> <span class=\"greek\">ποιῆσαι</span> «em tempo demasiado curto acreditas que estás fazendo de mim um cristão» (assim Bachmann, Blass). <span class=\"greek\">οὐ</span> <span class=\"greek\">πείθομαι</span> com acusativo e infinitivo, «não posso acreditar» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:26</a>.<br><br>ⓑ Obedecer, seguir, com dativo de pessoa ou coisa (Hom. e outros; Diod S 4, 31, 5 <span class=\"greek\">τῷ</span> <span class=\"greek\">χρησμῷ</span> = «ao oráculo»; Maximus Tyr. 23, 2d <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; 36, 6g <span class=\"greek\">τ</span>. <span class=\"greek\">νόμῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span>; Appian, Iber. 19 §73 <span class=\"greek\">θεῶ</span>; papiros; 4 Macc 10:13; 15:10; 18:1; Just., D. 9, 1; Mel., P. 93, 705; <span class=\"greek\">π</span>. <span class=\"greek\">θεῷ</span> Did., Gen. 225, 17; <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀδικίᾳ</span> Theoph. Ant. 1, 14 [p. 92, 5]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:8</a> (oposto a <span class=\"greek\">ἀπειθεῖν</span>, como Himerius, Or. 69 [=Or. 22], 7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:1</a>, variante textual; 5:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:3</a>; 2 Cl 17:5; Dg 5:10; IRo 7:2ab; Hm 12, 3, 3.<br><br>ⓒ Algumas passagens situam-se entre a e b, admitindo ambas as traduções, com dativo: «ser persuadido por alguém, acolher o conselho de alguém» ou «obedecer, seguir alguém»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:36f</a>, 39; 23:21; 27:11 (objeção de um passageiro à qual a tripulação não deu atenção e, por isso, sofreu dano: Chion, Ep. 4, 1 <span class=\"greek\">οἳ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπείθοντο</span>. Sobre a relação entre líderes heréticos e seus adeptos, Iren. 3, 12, 5 [Harv. II 58, 10]).<br><br>④ Perfeito passivo <span class=\"greek\">πέπεισμαι</span>: alcançar certeza a respeito de algo, estar convencido, seguro (Pla.+; papiros, LXX): <span class=\"greek\">πεπεισμένος</span> <span class=\"greek\">τοῦτο</span> «convencido disto» B 1:4. <span class=\"greek\">πέπεισμαί</span> <span class=\"greek\">τι</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> «estar convencido de alguma coisa a respeito de alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:9</a>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> «estar certo de alguma coisa» IPol 2:3. Seguido de acusativo e infinitivo (Diod S 12, 20, 2 <span class=\"greek\">πεπεῖσθαι</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">εἶναι</span>; PPetr II, 11, 4 [III a.C.]; EpArist 5; Just., D. 58, 2; Mel., HE 4, 26, 11; Ath. 36, 1f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:6</a>. Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> e acusativo seguido de infinitivo: <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">πέπεισμαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἔχειν</span> «sobre isso estou certo de que convosco é assim» ITr 3:2. Seguido de <span class=\"greek\">ὅτι</span> (X., Oec. 15, 8; Just., D. 65, 2; Tat., 20, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:38</a>; 14:14 (com <span class=\"greek\">οἶδα</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a>, 12 (cf. seguido de <span class=\"greek\">ὡ</span> em Did., Gen. 131, 8); Pol 9:2. <span class=\"greek\">πέπεισμαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:14</a>.—B. 1206; 1339. DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. EDNT. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πειλᾶτος</h1><div class=\"entry-meta\"><span>remissão de nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πειλᾶτος</span>: veja <span class=\"greek\">Πιλᾶτος</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεῖν</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πεῖν</span>: veja <span class=\"greek\">πίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεινάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πεινάω</span> (<span class=\"greek\">πεῖνα</span> «fome»; Hom. e outros; PFlor 61, 54; LXX; TestJob 23:8; ParJer 9:20; Philo, Joseph.; Tat. 23, 1), forma alternativa do particípio presente acusativo <span class=\"greek\">πεινοῦντα</span> (TestJob 23:8; veja B-D-F §90); futuro <span class=\"greek\">πεινάσω</span>; 1.º aoristo <span class=\"greek\">ἐπείνασα</span> (sobre as formas em <span class=\"greek\">α</span>, compartilhadas por nossa literatura com a LXX em oposição ao grego mais antigo, veja Phryn. p. 61 Lob.; B-D-F §70, 2; §88; Mlt-H. 195; 253).<br><br>① Sentir as dores da falta de alimento, ter fome, estar faminto (Iren. 3, 22, 2 [Harv. II 122, 6]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:2</a>; 12:1, 3; 21:18; 25:35, 37, 42, 44; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:25</a>; 11:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:2</a>; 6:3, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:20</a> (Pr 25:21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:34</a>; B 10:3. Oposto a <span class=\"greek\">μεθύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:21</a>. Oposto a <span class=\"greek\">χορτάζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πεινῶν</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">πεινῶντες</span> «aquele que tem fome, aqueles que têm fome» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:53</a> (cf. Ps 106:9; Tat. 23, 1); 6:21; 1 Cl 59:4; B 3:3 (Is 58:7), 5 (Is 58:10); Hv 3, 9, 5. Com <span class=\"greek\">διψᾶν</span> (<span class=\"greek\">διψάω</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:16</a> (Is 49:10); ISm 6:2.<br><br>② Desejar intensamente alguma coisa, ter fome de algo, extensão figurada de 1 (X., Pla. e outros, mas com genitivo da coisa. Para o acusativo, cf. <span class=\"greek\">διψάω</span> 2 e Zosimus: Hermet. IV p. 111, 3 <span class=\"greek\">πεῖν</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">σὴν</span> <span class=\"greek\">ψυχήν</span>), com acusativo de coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:6</a> (com <span class=\"greek\">διψᾶν</span>, como Plut., Mor. 460b; Jer 38:25). Sobre o anseio pelo alimento espiritual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:35</a> (também com <span class=\"greek\">διψᾶν</span>. Cf. ParJer 9:20 <span class=\"greek\">ἐμπλήσει</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">πεινώσας</span> <span class=\"greek\">ψυχάς</span> [Jer 38, 25]).—DELG s.v. <span class=\"greek\">πείνη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεῖρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πεῖρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">πειράζω</span>; Pind.+).<br><br>① Esforço para realizar alguma coisa, tentativa, prova, experimentação, em sentido ativo (Jos., C. Ap. 2, 183); <span class=\"greek\">πεῖραν</span> <span class=\"greek\">λαμβάνειν</span> «tentar, experimentar» (trágicos e outros; POxy 1681, 10; Dt 28:56), <span class=\"greek\">τινός</span> «alguém ou alguma coisa» (X., Cyr. 6, 1, 54, Mem. 1, 4, 18; Pla., Protag. 342a, Gorg. 448a; Polyb. 2, 32, 5; Jos., Ant. 8, 166; SEG VIII, 574, 21 [III d.C.]; UPZ 110, 129 [164 a.C.]) <span class=\"greek\">ἧς</span> <span class=\"greek\">πεῖραν</span> <span class=\"greek\">λαβόντες</span> «quando tentaram fazê-lo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:29</a>. Sobre <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span> <span class=\"greek\">πεῖραν</span> <span class=\"greek\">ἀθλῶμεν</span> 2 Cl 20:2, veja <span class=\"greek\">ἀθλέω</span>.<br><br>② Experiência adquirida pela tentativa de algo, experiência, em sentido passivo (X. e outros; IMagnMai 115, 21; Philo; Test Gad 5:2 <span class=\"greek\">ἐκ</span> <span class=\"greek\">πείρας</span>); <span class=\"greek\">πεῖράν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">λαμβάνειν</span> «experimentar algo» ou simplesmente «ter a experiência de alguma coisa» (Polyb. 6, 3, 1; 28, 9, 7; Diod S 12, 24, 4 <span class=\"greek\">τὴν</span> <span class=\"greek\">θυγατέρα</span> <span class=\"greek\">ἀπέκτεινεν</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὕβρεως</span> <span class=\"greek\">λάβῃ</span> <span class=\"greek\">πεῖραν</span>; Vett. Val. 74, 23; 82, 1; 84, 28 e outros; Jos., Ant. 2, 60, Vi. 160); <span class=\"greek\">μαστίγων</span> <span class=\"greek\">πεῖραν</span> <span class=\"greek\">ἔλαβον</span> «experimentaram açoites» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:36</a>.—DELG. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πειράζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πειράζω</span>, imperfeito <span class=\"greek\">ἐπείραζον</span>; futuro <span class=\"greek\">πειράσω</span>; 1.º aoristo <span class=\"greek\">ἐπείρασα</span>, médio da 2.ª pessoa do singular <span class=\"greek\">ἐπειράσω</span>. Passivo: 1.º aoristo <span class=\"greek\">ἐπειράσθην</span>; particípio perfeito <span class=\"greek\">πεπειρασνένος</span> (de <span class=\"greek\">πεῖρα</span>; Hom., depois Apollon. Rhod. 1, 495; 3, 10. Na prosa, desde Philo Mech. 50, 34; 51, 9; também Polyb.; Plut., Cleom. 808 [7, 3], Mor. 230a; Vett. Val. 17, 6; escólio sobre Aristoph., Pl. 575; PSI 927, 25 [II d.C.]; LXX; TestJos 16:3, variante textual; ApcSed 8:5 p. 133, 5 Ja.; Joseph.; Just., D. 103, 6; 125, 4.—B-D-F §101 p. 54; Mlt-H. 387 n. 1; 404).<br><br>① Empreender esforço para fazer alguma coisa, tentar, procurar, por vezes em contexto que indica inutilidade (<span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πειράζοντι</span> <span class=\"greek\">δοὺς</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διωκειν</span> <span class=\"greek\">ἡμᾶς</span> Orig., C. Cels. 8, 70, 11), seguido de infinitivo (Polyb. 2, 6, 9; Dt 4:34.—B-D-F §392, 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:26</a>; 16:7; 24:6; Hs 8, 2, 7. Seguido de acusativo com infinitivo IMg 7:1. Absolutamente Hs 8, 2, 7.<br><br>② Procurar descobrir a natureza ou o caráter de alguma coisa por meio de teste, tentar, experimentar, pôr à prova.<br><br>ⓐ Em geral, <span class=\"greek\">τινά</span> «alguém» (Epict. 1, 9, 29; Ps 25:2), <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">πειράζετε</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">ἐστὲ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> «examinai-vos para ver se estais na fé» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:5</a> (<span class=\"greek\">π</span>. <span class=\"greek\">εἰ</span> como Jos., Bell. 4, 340). <span class=\"greek\">ἐπείρασας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λέγοντας</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">ἀποστόλους</span> «puseste à prova os que se dizem apóstolos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:2</a>. <span class=\"greek\">προφήτην</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πειράσετε</span> <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">διακρινεῖτε</span> «não poreis à prova nem julgareis um profeta» D 11:7.<br><br>ⓑ Acerca de Deus ou de Cristo, que põem pessoas à prova em sentido favorável (Ps.-Apollod. 3, 7; 7, 4 Zeus põe à prova <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀσέβειαν</span> de certas pessoas), para que elas demonstrem sua fidelidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:17</a> (Abraão, como em Gen 22:1). Também acerca das provações dolorosas enviadas por Deus (Ex 20:20; Dt 8:2, variante textual; Judg 2:22; Wsd 3:5; 11:9; Jdth 8:25f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:18ab</a>; 4:15 (veja <span class=\"greek\">πειράω</span>); 11:37, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a> (SBrown, JBL 85, ’66, 308–14 <span class=\"greek\">π</span>. = «afligir»). Igualmente, acerca das medidas tomadas pelo anjo do arrependimento, Hs 7:1.<br><br>ⓒ A Bíblia (mas veja a Pítia em Hdt. 6, 86, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">πειρηθῆναι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">ἴσον</span> <span class=\"greek\">δύνασθαι</span> «tentar a divindade era tão grave quanto cometer o ato»; cf. 1, 159) também fala da prova de Deus pelos seres humanos. Sua intenção é pôr Deus à prova, descobrir se Deus realmente pode fazer determinada coisa, sobretudo se percebe o pecado e é capaz de puni-lo (Ex 17:2, 7; Num 14:22; Is 7:12; Ps 77:41, 56; Wsd 1:2 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:9</a> (Ps 94:9). <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:9</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:10</a>, <span class=\"greek\">πειράζειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> consiste no fato de que, após a vontade de Deus ter sido claramente manifestada pela concessão do Espírito aos gentios (v. 8), alguns duvidam e põem à prova se essa vontade realmente se concretiza. <span class=\"greek\">τὸν</span> <span class=\"greek\">διά</span> <span class=\"greek\">σου</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">πειράσαι</span> <span class=\"greek\">θέλων</span>, <span class=\"greek\">εἰ</span> «pois desejo pôr à prova o Deus (que proclamas), para verificar se» AcPt Ox 849, 20–22, seguido de <span class=\"greek\">οὐ</span> <span class=\"greek\">πειράζεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> «Deus se recusa a ser posto à prova».—ASommer, D. Begriff d. Versuchung im AT u. Judentum, dissertação, Breslau ’35. Veja <span class=\"greek\">πειράω</span>.<br><br>③ Tentar apanhar alguém numa armadilha mediante perguntas, pôr à prova. Assim Jesus foi tratado por seus adversários, que pretendiam usar suas respostas contra ele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:1</a>; 19:3; 22:18, 35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:11</a>; 10:2; 12:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:16</a>; 20:23, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:6</a>.<br><br>④ Seduzir a uma conduta indevida, tentar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:13a</a> (veja <span class=\"greek\">ἀπό</span> 5e<span class=\"greek\">β</span>) e b, 14 (Aeschin. 1, 190: os deuses não induzem as pessoas ao pecado). Sobretudo o diabo age dessa forma; por isso é chamado diretamente <span class=\"greek\">ὁ</span> <span class=\"greek\">πειράζων</span> «o tentador» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5b</a>. Ele tenta os seres humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:3</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:10</a>. Mas também se atreve a tentar Jesus (Just.. D. 103, 6; Orig., C. Cels. 6, 43, 28) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:2</a> (cf. uso do passivo sem referência ao diabo: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πειράζεσθαι</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">σταυροῦσθαι</span> Iren. 3, 19, 3 [Harv. II 104, 3].—Did., Gen. 225, 2). Sobre a tentação de Jesus (veja também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:18a</a>; 4:15; 2b acima), veja HWillrich, ZNW 4, 1903, 349f; KBornhäuser, Die Versuchungen Jesu nach d. Hb: MKähler Festschr. 1905, 69–86; sobre isso Windisch, Hb2 ’31, 38, excurso sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:15</a>; AHarnack, Sprüche u. Reden Jesu 1907, 32–37; FSpitta, Zur Gesch. u. Lit. des Urchristentums III 2, 1907, 1–108; AMeyer, Die evangel. Berichte üb. d. Vers. Christi: HBlümner Festschr. 1914, 434–68; DVölter, NThT 6, 1917, 348–65; EBöklen, ZNW 18, 1918, 244–48; PKetter, D. Versuchg. Jesu 1918; BViolet, D. Aufbau d. Versuchungsgeschichte Jesu: Harnack Festschr. 1921, 14–21; NFreese, D. Versuchg. Jesu nach den Synopt., dissertação, Halle 1922, D. Versuchlichkeit Jesu: StKr 96/97, 1925, 313–18; SEitrem/AFridrichsen, D. Versuchg. Christi 1924; Clemen2 1924, 214–18; HVogels, D. Versuchungen Jesu: BZ 17, 1926, 238–55; SelmaHirsch [veja <span class=\"greek\">βαπτίζω</span> 2a]; HThielicke, Jes. Chr. am Scheideweg ’38; PSeidelin, DTh 6, ’39, 127–39; HHoughton, On the Temptations of Christ and Zarathustra: ATR 26, ’44, 166–75; EFascher, Jesus u. d. Satan ’49; RSchnackenburg, TQ 132, ’52, 297–326; K-PKöppen, Die Auslegung der Versuchungsgeschichte usw.’61; EBest, The Temptation and the Passion (Mk), ’65; JDupont, RB 73, ’66, 30–76.—B. 652f. DELG s.v. <span class=\"greek\">πεῖρα</span>. M-M. EDNT. DLNT 1166–70. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πειρασμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πειρασμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πειράζω</span>; no uso extrabíblico apenas Diosc., Mat. Med. Praef. 5; Cyranides; Syntipas [veja 2b].—LXX; TestJos 2:7).<br><br>① Tentativa de conhecer a natureza ou o caráter de alguma coisa, teste, prova (Sir 6:7; 27:5, 7), <span class=\"greek\">πρὸς</span> <span class=\"greek\">πειρασμόν</span> «para vos pôr à prova» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:12</a>. <span class=\"greek\">διὰπειρασμόν</span> <span class=\"greek\">τινα</span> «porque estais sendo provados de alguma maneira» Hm 9:7. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:2</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:6</a> pertençam aqui (cf. Pind., O. 4, 22 <span class=\"greek\">διά</span> <span class=\"greek\">πειρά</span> <span class=\"greek\">τοι</span> <span class=\"greek\">βροτῶν</span> <span class=\"greek\">ἔλεγχο</span> «a prova é a pedra de toque dos mortais»; semelhantemente N. 3, 70f). Também pertence aqui o ato de humanos porem Deus à prova (veja <span class=\"greek\">πειράζω</span> 2c; cf. Dt 6:16; 9:22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:8</a>, em que o v. 9 mostra que Deus é quem está sendo posto à prova, e não os israelitas (Ps 94:8f).<br><br>② Tentativa de levar alguém a praticar algo errado, tentação, indução ao pecado.<br><br>ⓐ Em sentido ativo: tentar. <span class=\"greek\">συντελέσας</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">διάβολος</span> «quando o diabo esgotou toda forma de tentação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:13</a>.<br><br>ⓑ Em sentido passivo: ser tentado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:12</a>. Tentação, vinda de fora ou de dentro, capaz de constituir ocasião de pecado para alguém (Sir 33:1; 44:20; 1 Macc 2:52; Orig., C. Cels. 8, 56, 9): <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰσενέγκῃς</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πειρασμόν</span> «não nos conduzas à tentação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:4</a> (veja bibliografia em The Lord’s Prayer and Other Prayer Texts fr. the Gr-Roman Era, ed. JCharlesworth ’94, 186–201); D 8:2; cf. Pol 7:2.—KKnoke, Der ursprüngl. Sinn der sechsten Bitte: NKZ 18, 1907, 200–220; AHarnack, Zur sechsten Bitte des Vaterunsers: SBBerlAk 1907, 942–47; AKleber, CBQ 3, ’41, 317–20; GVerity, ET 58, ’46/47, 221f; FGrant, Introd. to NT Thought, ’50, 208.—<span class=\"greek\">μέγα</span> <span class=\"greek\">ἐπίκειται</span> <span class=\"greek\">π</span>. «grande tentação está diante de mim» AcPl Ha 8, 22=Ox 1602, 31, conforme correção em HTR 31 ’38, 58 n. 2, ln. 10=BMM recto 28.—(<span class=\"greek\">εἰς</span>)<span class=\"greek\">έρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πειρασμόν</span> (Did., Gen. 225, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:38</a> (Unknown Sayings, tradução de Fuller ’57, p. 59 n. 1 e veja o ágrafo de Tertullian, pp. 57–59); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:40</a> (HBate, JTS 36, ’35, 76f), 46. <span class=\"greek\">ἐμπίπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πειρασμόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:9</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">πειρασμοῦ</span> «em tempo de tentação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:13</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">πειρασμοῦ</span> <span class=\"greek\">ῥύεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:9</a>. Cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:26</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13ab</a>; 2 Cl 18:2.—Também no plural, «tentações» (Cyranides p. 40, 24 <span class=\"greek\">πειρασμοὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γῇ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θαλάσσῃ</span>; Syntipas p. 124, 18; TestJos 2:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:28</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">ταπεινοφροσύνης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δακρύων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πειρασμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:19</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ποικίλοις</span> <span class=\"greek\">πειρασμοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:6</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:2</a> («prova» também é provável nessas duas últimas passagens; veja 1 acima).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:9</a>, variante textual.—Sobre a difícil expressão <span class=\"greek\">τὸν</span> <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκί</span> <span class=\"greek\">μου</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξουθενήσατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:14</a>, veja <span class=\"greek\">ἐξουθενέω</span> 1 e 2 e JdeZwaan, ZNW 10, 1909, 246–50.—HKorn, <span class=\"greek\">ΠΕΙΡΑΣΜΟΣ</span>. Die Versuchg. des Gläubigen in der griech. Bibel, ’37; MAndrews, Peirasmos, A Study in Form-Criticism, ATR 24, ’42, 229–44; KKuhn, <span class=\"greek\">πειρασμός</span> im NT, ZTK 49, ’52, 200–222, New Light on Temptation, etc., in The Scrolls and the NT, ed. Stendahl, ’57, 94–113.—M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πειράω</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πειράω</span>, em nossa literatura apenas <span class=\"greek\">πειράομαι</span> (Hom.+), futuro médio <span class=\"greek\">πειράσομαι</span>; 1.º aoristo plural <span class=\"greek\">ἐπειράθημεν</span> 1 Macc 12:10; perfeito <span class=\"greek\">πεπείραμαι</span> 1 Km 17:39; num lugar talvez como passivo, imperfeito, 3.ª pessoa do singular <span class=\"greek\">ἐπειρᾶτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:26</a>, variante textual; particípio perfeito <span class=\"greek\">πεπειραμένος</span>.<br><br>① Procurar fazer alguma coisa, tentar, experimentar, esforçar-se, seguido de infinitivo (Hom.+; inscrições, papiros, 2 Macc 2:23; 10:12; 3 Macc 2:32; 4 Macc 12:2; EpArist 297; Philo, Sacr. Abel. 123; Jos., C. Ap. 1, 70; 2, 283), <span class=\"greek\">Ἰουδαῖοί</span> <span class=\"greek\">με</span> <span class=\"greek\">ἐπειρῶντο</span> <span class=\"greek\">διαχειρίσασθαι</span> «os judeus tentaram matar-me» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:21</a>. Cf. 9:26, variante textual (em lugar de <span class=\"greek\">ἐπείραζεν</span>); 2 Cl 17:3; MPol 13:2; Qua 1.<br><br>② Ter uma experiência, experimentar. É difícil determinar o sentido da redação de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:15</a>, variante textual (em lugar de <span class=\"greek\">πεπειρασμένον</span>), que descreve Cristo como <span class=\"greek\">πεπειραμένος</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντα</span>. Partindo do significado «pôr alguém ou alguma coisa à prova para conhecê-la melhor», o médio pode significar «passar por experiência e aprender algo por meio dela» (Aesop, Fab. 105 H.//437 P.//p. 190 ln. 6 H-H.), e o perfeito médio, «ter experimentado, saber por experiência, conhecer» (Hes., Hdt. e outros; X., Hiero 1, 2; 2, 6; Pla., Ep. 6 p. 323a). Para nossa passagem, disso resultaria o sentido «aquele que possui experiência em todos os aspectos». O sentido passivo «posto à prova, testado, tentado» dificilmente se harmoniza com o uso grego. Veja <span class=\"greek\">πειράζω</span> 2b e 4 sobre a passagem de Hb.—B. 652f. DELG s.v. <span class=\"greek\">πεῖρα</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεισμονή, ῆς ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πεισμονή</span>, <span class=\"greek\">ῆς</span> <span class=\"greek\">ἡ</span> (de <span class=\"greek\">πείθω</span> por intermédio de <span class=\"greek\">πεῖσμα</span> «persuasão»; Apollon. Dysc.=Gramm. Gr. II 2 p. 429, 9 U.; 299, 17; Eustathius sobre Hom. diversas vezes; Just., A I, 53, 1; Iren. 4, 33, 7 [Harv. II 262, 2] e outros escritores eclesiásticos, veja Lampe s.v.), persuasão (Apollon.; Justin, loc. cit.; PLond V, 1674, 36 [VI d.C.]); <span class=\"greek\">οὐ</span> <span class=\"greek\">πεισμονῆς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">μεγέθους</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστιανισμός</span> «o cristianismo não é questão de persuasão, mas de (verdadeira) grandeza» IRo 3:3. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καλοῦντος</span> «essa persuasão, que vos desvia da verdade, não procede daquele que vos chama» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:8</a> (EBurton, ICC Gal 1920, 282f). B-D-F §488, 1b favorecem aqui o sentido «obediência» [Folgsamkeit] (também §109, 6), mas para tanto precisam afastar-se do texto grego transmitido pela grande maioria dos testemunhos.—DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλαγος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέλαγος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e outros; OGI 74, 3; IG XII/2, 119, 7; 2 Macc 5:21; TestSol; TestAbr A 17 p. 98, 27 [Stone p. 44]; TestNapht 6:5; EpArist 214; Philo, Joseph.; empréstimo em textos rabínicos).<br><br>① Mar aberto (em oposição à extensão de água próxima da terra), alto-mar, profundezas (do mar) (Aristot., Probl. Sect. 23 Quaest. 3, 931b, 14 f. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λιμένι</span> <span class=\"greek\">ὀλίγη</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θάλασσα</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πελάγει</span> <span class=\"greek\">βαθεῖα</span>; Jos., Bell. 1, 409), <span class=\"greek\">τὸ</span> <span class=\"greek\">πέλαγος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> (Apollon. Rhod. 2, 608. Cf. também Eur., Tro. 88 <span class=\"greek\">πέλαγος</span> <span class=\"greek\">Αἰγαίας</span> <span class=\"greek\">ἁλός</span>. Hesych.: <span class=\"greek\">πέλαγος</span> … <span class=\"greek\">βυθός</span>, <span class=\"greek\">πλάτος</span> <span class=\"greek\">θαλάσσης</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> «em alto-mar (nas profundezas do mar)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a> (Jos., C. Ap. 1, 307, acerca de leprosos, <span class=\"greek\">ἵνα</span> <span class=\"greek\">καθῶσιν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέλαγος</span>); semelhantemente, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">πέλαγει</span> AcPl Ha 7, 25.<br><br>② Parte independente de uma massa de água em seu conjunto, mar (uso predominante: Aeschyl. e outros; Diod S 4, 77, 6 <span class=\"greek\">τὸ</span> <span class=\"greek\">πέλ</span>. <span class=\"greek\">Ἰκάριον</span>; Philo, Op. M. 63; Jos., Ant. 2, 348), <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Κιλικίαν</span> «o mar ao longo da costa da Cilícia» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:5</a>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέλας</h1><div class=\"entry-meta\"><span>advérbio substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέλας</span>, advérbio (Hom. e outros), «perto»; <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. «o próximo, o vizinho» (assim Alcaeus 137 D.2; trágicos, Hdt.; Sextus 17; POxy 79 II, 9; Pr 27:2; Ath., 32, 2, R. 23 p. 76, 14) MPol 1:2 (conforme <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:4</a>, porém com <span class=\"greek\">τὸ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πέλας</span> em lugar de <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑτέρων</span>).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πελεκίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πελεκίζω</span>, particípio perfeito passivo <span class=\"greek\">πεπελεκισμένος</span>, «decapitar (com machado)» (<span class=\"greek\">πέλεκυς</span>), normalmente ato de execução capital (Polyb. 1, 7, 12; 11, 30, 2; Diod S 19, 101, 3; Strabo 16, 2, 18; Plut., Ant. 36, 4; Jos., Ant. 20, 117; empréstimo em textos rabínicos) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:4</a>.—B. 561. DELG s.v. <span class=\"greek\">πέλεκυς</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεμπταῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πεμπταῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">πέμπτος</span>; Hom. e outros; papiros; EpArist 175), relativo ao quinto (dia), no quinto (dia); <span class=\"greek\">ἤλθομεν</span> <span class=\"greek\">πεμπταῖοι</span> «chegamos em cinco dias» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:6</a> D (Diod S 14, 103, 2 <span class=\"greek\">π</span>. = «no quinto dia»; Arrian, Anab. 1, 29, 1 <span class=\"greek\">ἀφικνεῖται</span> <span class=\"greek\">πεμπταῖος</span>).—DELG s.v. <span class=\"greek\">πέντε</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμπτος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo numeral ordinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέμπτος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πέντε</span>; Hom. e outros), numeral ordinal «quinto» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:9</a>; 9:1; 16:10; 21:20; Hv 3, 1, 2; Hs 9, 1, 7; 9, 22, 1. <span class=\"greek\">ἡ</span> <span class=\"greek\">πέμπτη</span>, isto é, <span class=\"greek\">ἡμέρα</span> «o quinto dia» (Hes., Aristoph. e outros; Jos., Vi. 47), <span class=\"greek\">σαββάτων</span> <span class=\"greek\">πέμπτῃ</span> «no quinto dia da semana», isto é, «na quinta-feira», segundo a contagem judaico-cristã, D 8:1.—DELG s.v. <span class=\"greek\">πέντε</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέμπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέμπω</span>, futuro <span class=\"greek\">πέμψω</span>; 1.º aoristo <span class=\"greek\">ἑπεμψα</span>; perfeito <span class=\"greek\">πέπομφα</span> IEph 17:2. Passivo: infinitivo futuro <span class=\"greek\">πεμφθήσεσθαι</span> (Just., A I, 28); 1.º aoristo <span class=\"greek\">ἐπέμφθην</span>; particípio do 1.º perfeito <span class=\"greek\">πεπεμμένος</span> (Just., D. 126, 6); mais-que-perfeito, 3.ª pessoa do singular <span class=\"greek\">ἐπέπεμπτο</span> Just., D. 56, 5).<br><br>① Despachar alguém, seja um ser humano ou transcendente, normalmente para fins de comunicação, enviar, <span class=\"greek\">τινά</span> «alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:22</a>; 13:16; 20:21b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:23</a>, 28; ISm 11:3. <span class=\"greek\">δοῦλον</span> «um servo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:11</a>; cf. vv. 12f. <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:3</a>. <span class=\"greek\">ἄνδρας</span> <span class=\"greek\">πιστούς</span> «homens de confiança» 1 Cl 63:3. <span class=\"greek\">ὑπηρέτην</span> «um auxiliar» Dg 7:2. <span class=\"greek\">ἐπισκόπους</span> «bispos» IPhld 10:2. Com duplo acusativo, <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">κατάσκοπον</span> «enviar alguém como espião» B 12:9; com acusativo de particípio, <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">κρίνοντα</span> «enviar alguém como juiz» Dg 7:6. <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">πρεσβεύσοντα</span> «enviar alguém como representante» Pol 13:1. Com indicação de destino (a referência a uma missão ou delegação por vezes é omitida por ser evidente, como no inglês «enviar a alguém» = «enviar um mensageiro a alguém»): <span class=\"greek\">π</span>. (<span class=\"greek\">τινὰ</span>) <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> «enviar (alguém) a, para dentro de» (X., Hell. 7, 4, 39; Jos., C. Ap. 1, 271 <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἱερος</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:15</a>; 16:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:5</a>, 32 (sem acusativo); 15:22; IEph 6:1; GJs 16:2. Com ponto de partida e destino indicados, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Μιλήτου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἔφεσον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:17</a> (sem acusativo). Com indicação da pessoa a quem alguém é enviado, <span class=\"greek\">π</span>. (<span class=\"greek\">τινὰ</span>) <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> «enviar (alguém) a alguém» (X., Cyr. 1, 5, 4; Demetr.: 722 Fgm. 1:13 Jac.; Diod S 20, 72, 1 <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Συρακούσας</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφόν</span>; PHib 127 descr. 3 [III a.C.] <span class=\"greek\">π</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>; Sb 6769, 5; 2 Esdr 5:17; En 10:2; TestJos 9:1; Manetho: 609 Fgm. 10 Jac. [em Jos., C. Ap. 1, 241]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:19</a> (<span class=\"greek\">αὐτούς</span> «eles» é suprido pelo contexto imediato); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33</a> (sem acusativo); 15:25; 19:31 (sem acusativo); 23:30 (o acusativo <span class=\"greek\">αὐτόν</span> «ele» é suprido pelo contexto.—Veja mais abaixo, onde essa passagem é citada novamente); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:8</a>; Tit 3:12; GJs 21:2, códices. Em várias dessas passagens <span class=\"greek\">π</span>. é empregado com outro verbo que expressa o propósito do envio. Esse verbo pode aparecer no particípio: <span class=\"greek\">ἔπεμψεν</span> <span class=\"greek\">λέγων</span> «enviou para perguntar» (cf. Gen 38:25; 2 Km 14:32; Jos., C. Ap. 1, 262) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:19</a>; cf. v. 6. Ou o verbo associado a <span class=\"greek\">π</span>. aparece numa forma finita e <span class=\"greek\">π</span>. fica no particípio (Appian, Bell. Civ. 5, 9 §34 <span class=\"greek\">πέμψας</span> <span class=\"greek\">ἀνεῖλε</span> = «enviou e mandou matar [ela]»; 5, 118 §489 <span class=\"greek\">ἤρετο</span> <span class=\"greek\">πέμπων</span> = «enviou e perguntou»; Gen 27:42; Jos., Ant. 7, 149): <span class=\"greek\">πέμψαντες</span> <span class=\"greek\">παρεκάλουν</span> «enviaram e aconselharam» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:31</a>; cf. <span class=\"greek\">πέμψας</span> <span class=\"greek\">ἀπεκεφάλισεν</span> «enviou e mandou decapitar (João)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:10</a>.—22:7. Diferentemente, <span class=\"greek\">πέμψας</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">εἶπεν</span> «enviou-os e disse» 2:8. Com indicação, no dativo, daquele que deve receber alguém, <span class=\"greek\">π</span>. <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> «enviar alguém a alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:19</a>.—<span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰω</span>. <span class=\"greek\">πέμψας</span> <span class=\"greek\">δύο</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">αὐτῷ</span> = «enviou dois de seus discípulos e fez com que lhe dissessem» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:2</a>, variante textual (cf. Appian, Bell. Civ. 1, 96 §449 <span class=\"greek\">πέμψας</span> <span class=\"greek\">τινὰς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Πομπήιος</span> <span class=\"greek\">συνέλαβεν</span> [<span class=\"greek\">Κάρβωνα</span>] = «Pompeu enviou alguns homens e mandou deter [Carbo]»). Com o propósito indicado pelo infinitivo (Just., D. 45, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:3</a>; cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:16</a>. Com infinitivo substantivado seguido de <span class=\"greek\">εἰς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>, 5. Com <span class=\"greek\">εἰς</span> (Appian, Mithrid. 108 §516 <span class=\"greek\">ἔπεμπεν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">θυγατέρας</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">γάμους</span> = «para casá-las [com príncipes citas]»): <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">τοῦτο</span> «para esse mesmo propósito» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:8</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐκδίκησιν</span> <span class=\"greek\">κακοποιῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:14</a>. Com <span class=\"greek\">εἰς</span> duas vezes: <span class=\"greek\">εἰς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Σμύρναν</span> IEph 21:1. Com o propósito indicado por <span class=\"greek\">ἵνα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:24</a>.—Especialmente acerca do envio dos representantes de Deus (Aberciusins. 7; Philosoph. Max. 497, 8, o sábio é <span class=\"greek\">ἀποσταλείς</span>, seu <span class=\"greek\">πέμψας</span> é Deus): Moisés 1 Cl 17:5; Elias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:26</a>. O anjo do arrependimento Hs 8, 11, 1. Sobretudo o Pai envia o Filho (à terra) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:3</a>; IMg 8:2. <span class=\"greek\">πέμψω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀγαπητόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:13</a> (cf. Hdt. 1, 119, 2f <span class=\"greek\">ἦν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">παῖς</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">μοῦνος</span> … <span class=\"greek\">τοῦτον</span> <span class=\"greek\">ἐκπέμπει</span> … <span class=\"greek\">ἐς</span> <span class=\"greek\">Ἀστυάγεος</span> … <span class=\"greek\">Ἀστυάγης</span> <span class=\"greek\">σφάξας</span> <span class=\"greek\">αὐτόν</span>). O Evangelho de João é dominado pelo pensamento de que Jesus é enviado por Deus do céu (veja o excurso do Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:17</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:34</a>; 5:23f, 30, 37; 6:38f, 44; 7:16, 28, 33; 8:16, 18, 26, 29; 9:4; 12:44f, 49; 13:20; 14:24; 15:21; 16:5. Jesus, ou Deus em seu nome, enviará o Paráclito ou Espírito Santo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:26</a>; 15:26 (<span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">πέμψω</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>); 16:7. De modo semelhante, <span class=\"greek\">πέμπει</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">πλάνης</span> «Deus lhes envia uma influência enganadora» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:11</a>.—A ideia de deslocar-se de um lugar para outro, inerente a «enviar», pode recuar para segundo plano, de modo que <span class=\"greek\">π</span>. assuma o sentido de instruir, incumbir, designar: <span class=\"greek\">ὁ</span> <span class=\"greek\">πέμψας</span> <span class=\"greek\">με</span> <span class=\"greek\">βαπτίζειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὕδατι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:33</a>. Cf. 7:18 e o passivo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:14</a>. Em outros lugares também <span class=\"greek\">π</span>. assume significado particular em função do contexto: <span class=\"greek\">πέμψον</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">χοίρους</span> «manda-nos entrar nos porcos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:12</a>. Sobre alguém preso, «mandar transportá-lo até o destino» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:25</a>, 27; cf. 23:30 (sobre essas passagens, veja TGagos/PSijpesteijn, BASP 33, ’96, 77–97).—Absolutamente, <span class=\"greek\">οἱ</span> <span class=\"greek\">πεμφθέντες</span> «os que foram enviados» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:10</a>.—Em várias das passagens já mencionadas (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:8</a>), <span class=\"greek\">ἔπεμψα</span> é um aoristo epistolar (Thu. 1, 129, 3; Chion, Ep. 15, 3 <span class=\"greek\">ἔπεμψα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀντίγραφον</span>; POxy 937, 21.—B-D-F §334; Rob. 845f).<br><br>② Despachar alguma coisa por intermédio de alguém, enviar, <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> «alguma coisa a alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:10</a>; Hv 2, 4, 3a; Hs 5, 2, 9; 5, 5, 3. O objeto enviado pode deixar de ser expresso quando é facilmente suprido pelo contexto: <span class=\"greek\">πέμψον</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ἐκκλησίαις</span>, <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἔφεσον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> … «envia (o livro) às sete igrejas, a Éfeso e a …» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:11</a>. <span class=\"greek\">πέμψει</span> <span class=\"greek\">Κλήμης</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἔξω</span> <span class=\"greek\">πόλεις</span> «Clemente deverá enviá-lo (= sua cópia ou cópias dele) às cidades de fora» Hv 2, 4, 3b. <span class=\"greek\">ὥρισαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">διακονίαν</span> <span class=\"greek\">πέμψαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span> «resolveram enviar (alguma coisa) aos irmãos para seu sustento» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:29</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χρείαν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐπέμψατε</span> «enviaste-me (o que era necessário) para satisfazer minhas necessidades» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:16</a> (cf. variantes textuais sem a preposição <span class=\"greek\">εἰς</span> e veja Ar. Milne p. 74 ln. 26: <span class=\"greek\">πέμπουσιν</span> <span class=\"greek\">αὐτοῖ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">χρέαν</span> <span class=\"greek\">ἔχουσιν</span>). Figuradamente, <span class=\"greek\">μερίσας</span> … <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">ἔπεμψεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">προφήτας</span> «(Deus) enviou aos profetas uma porção do Espírito de Cristo» AcPlCor 2:10.—Sobre <span class=\"greek\">π</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">δρέπανον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:15</a>, 18, veja <span class=\"greek\">δρέπανον</span>.—<span class=\"greek\">π</span>. <span class=\"greek\">διά</span> <span class=\"greek\">τινος</span> pode derivar do AT (= <span class=\"hebrew\" dir=\"rtl\">שָׁלַח</span> <span class=\"hebrew\" dir=\"rtl\">בְּיַד</span> <span class=\"hebrew\" dir=\"rtl\">פּ׳</span> 1 Km 16:20; 2 Km 11:14; 3 Km 2:25) e pode ter dado origem à expressão <span class=\"greek\">πέμψας</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μαθητῶν</span> <span class=\"greek\">εἶπεν</span> <span class=\"greek\">αὐτῷ</span> «enviou mensagem por intermédio de seus discípulos e disse-lhe» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:2</a> ([Just., D. 53, 1]; mas expressão semelhante ocorre em Appian, Mithrid. 108 §516 <span class=\"greek\">ἔπεμπεν</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">εὐνούχων</span>).—<span class=\"greek\">π</span>. absolutamente significa enviar, escrever documento, carta etc. (Ps.-Callisth. 3, 18, 4; PGiss 13, 5 [II d.C.] <span class=\"greek\">Ἀρσινόη</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἔπεμψε</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ταλάντων</span>; 17, 8; 13; 27, 8 <span class=\"greek\">οὗ</span> <span class=\"greek\">ἕνεκα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">ἔπεμψα</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐπιγνῶ</span>; 81, 6; 14 <span class=\"greek\">πέμψον</span> <span class=\"greek\">μοι</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">σου</span> e frequentemente em papiros) <span class=\"greek\">ἐσπούδασα</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πέμπειν</span> «empenhei-me em escrever-vos brevemente» B 1:5.—DELG. M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0278-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πένης, ητος</h1><div class=\"entry-meta\"><span>substantivo e adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πένης</span>, <span class=\"greek\">ητος</span> (<span class=\"greek\">πένομαι</span> «trabalhar, labutar»; Soph., Hdt. e outros; Jos., Ant. 14, 31), referente àquele que é obrigado a trabalhar para ganhar a vida, mas não foi reduzido à mendicância; para esse último aspecto normalmente se emprega <span class=\"greek\">πτωχός</span>, veja esse verbete (cf. Aristoph., Plut. 552f <span class=\"greek\">πτωχοῦ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">βίος</span>, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">σὺ</span> <span class=\"greek\">λέγεις</span>, <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἔχοντα</span>· <span class=\"greek\">τοῦ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πένητος</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">φειδόμενον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">προσέχοντα</span> = «pois a vida do mendigo que descreves consiste em existir sem nada possuir, mas a do pobre consiste em viver parcimoniosamente e dedicar-se ao trabalho»), oposto a <span class=\"greek\">πλούσιος</span>, «pobre, necessitado»; em nossa literatura, apenas substantivado <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. «a pessoa pobre» (Pla., X. e outros; PRyl 62, 11; PRein 47, 11; LXX; pseudoepígrafos; Philo; Jos., Bell. 4, 379, Ant. 7, 149; Ar., Tat.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:9</a> (Ps 111:9); 1 Cl 15:6 (Ps 11:6. Sobre a justaposição, aqui e em outras passagens da LXX, de <span class=\"greek\">πένης</span> e <span class=\"greek\">πτωχός</span> [veja também PsSol 5:11; TestJob 12:1; 32:2; TestAsh 2:6]; Ammonius Gr. [100 d.C.] p. 108 Valck.; PFlor 296, 18); GJs 20:1, códices. Em oposição a <span class=\"greek\">ὁ</span> <span class=\"greek\">πλούσιος</span> (X., An. 7, 7, 28; Pla., Prot. 319d; Plut., Pericl. 155 [7, 3]; PSI 120, 47; 2 Km 12:1; 1 Esdr 3:19; Pr 23:4; EpArist 249; TestAbr A; TestReub 4:7; Tat. 11, 1) Hs 2:5ff; B 20:2; D 5:2. Com <span class=\"greek\">χήρα</span>, <span class=\"greek\">ὀρφανός</span> Pol 6:1.—JHemelrijk, <span class=\"greek\">Πενία</span> en <span class=\"greek\">Πλοῦτος</span>, dissertação, Utrecht 1925; JJvanManen, <span class=\"greek\">Πενία</span> en <span class=\"greek\">Πλοῦτος</span> in de periode na Alexander, dissertação, Utrecht ’31.—B. 782. Schmidt, Syn. II 611–25. DELG s.v. <span class=\"greek\">πένομαι</span>. M-M. TW.</p></section></article>"};
